public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        return "appx(null, null) = 0";
    }

    // Convert to uppercase for case-insensitive comparison
    String w1 = word1.toUpperCase();
    String w2 = word2.toUpperCase();

    // Count common letters (each letter counted once per word, i.e., min frequency)
    int[] freq1 = new int[26];
    int[] freq2 = new int[26];

    for (char c : w1.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq1[c - 'A']++;
        }
    }
    for (char c : w2.toCharArray()) {
        if (c >= 'A' && c <= 'Z') {
            freq2[c - 'A']++;
        }
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(freq1[i], freq2[i]);
    }

    int sumLengths = w1.length() + w2.length();

    // Handle division by zero
    if (sumLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Reduce the fraction common/sumLengths
    int numerator = common;
    int denominator = sumLengths;

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

