        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Ascending pass: pick smallest available, then next smallest, etc.
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }

        // Descending pass: pick largest available, then next largest, etc.
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
